"""NVSS/CDC WONDER monthly suicide mortality 1999-2024: school-calendar seasonality at 12-17 vs 18-24/25-34, the summer-vs-school-month
decomposition of the post-2010 rise, the 2020 closure contrast and the day-of-week pattern (tables from scripts/analysis/30_nvss_seasonality.py)."""
import datetime as dt

def build(ctx):
    pd, np, go = ctx.pd, ctx.np, ctx.go; T = ctx.T
    M = pd.read_csv(T/"nvss_monthly_counts.csv"); PROF = pd.read_csv(T/"nvss_seasonal_profile.csv"); RAT = pd.read_csv(T/"nvss_season_ratios.csv")
    DEC = pd.read_csv(T/"nvss_decomposition.csv"); REG = pd.read_csv(T/"nvss_poisson.csv"); COV = pd.read_csv(T/"nvss_covid_2020.csv"); WK = pd.read_csv(T/"nvss_weekday.csv"); A = pd.read_csv(T/"nvss_annual.csv")
    SEX = {"F": "girls", "M": "boys", "A": "both sexes"}; SEXC = {"F": ctx.GIRL, "M": ctx.BOY, "A": ctx.ALL}; SEXT = {"F": "Girls", "M": "Boys", "A": "Both"}
    MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]
    def r1(x): return f"{x:.1f}"
    def pct(x, d=0): return f"{round(x, d) + 0.0:+.{d}f}%"   # + 0.0 turns -0.0 into +0
    def ci(lo, hi, d=2): return f"{lo:.{d}f}–{hi:.{d}f}"
    def rat(df, period, g, sx): return df[(df.period == period) & (df.agegrp == g) & (df.sex == sx)].iloc[0]
    def dec(pre, post, g, sx): return DEC[(DEC.pre == pre) & (DEC.post == post) & (DEC.agegrp == g) & (DEC.sex == sx)].iloc[0]
    def reg(model, term, g, sx, est="poisson"): return REG[(REG.model == model) & (REG.term == term) & (REG.agegrp == g) & (REG.sex == sx) & (REG.estimator == est)].iloc[0]
    def cov(g, sx, year, window): return COV[(COV.agegrp == g) & (COV.sex == sx) & (COV.year == year) & (COV.window == window)].iloc[0]
    def ann(g, sx, y): return A[(A.agegrp == g) & (A.sex == sx) & (A.year == y)].iloc[0]
    n_deaths = {g: int(M[(M.agegrp == g) & (M.sex == "A") & (M.year <= 2024)].deaths.sum()) for g in ("12-17", "18-24", "25-34")}
    y0, y1 = int(M.year.min()), int(M.year.max())

    # ---------- chart 1: monthly rates 12-17, 2008-2024, summers shaded ----------
    fig = go.Figure(); s = M[(M.agegrp == "12-17") & (M.year >= 2008)].copy(); s["date"] = pd.to_datetime(dict(year=s.year, month=s.month, day=15))
    for sx in ("M", "F"):
        q = s[s.sex == sx]; fig.add_trace(go.Scatter(x=q.date, y=q.rate, mode="lines", name=f"{SEXT[sx]} 12–17", line=dict(color=SEXC[sx], width=2)))
    for y in range(2008, 2025): fig.add_vrect(x0=dt.date(y, 6, 1), x1=dt.date(y, 9, 1), fillcolor="rgba(128,128,128,.10)", line_width=0)
    fig.add_vrect(x0=dt.date(2020, 3, 1), x1=dt.date(2020, 6, 1), fillcolor="rgba(235,104,52,.12)", line_width=0, annotation_text="Mar–May 2020", annotation_position="top left", annotation_font_size=10)
    fig.update_yaxes(title_text="Suicides per 100,000 person-years", rangemode="tozero"); fig.update_xaxes(dtick="M12", tickformat="%Y")
    ctx.figs["nvss_monthly"] = ctx.base(fig, h=360)

    # ---------- chart 2: seasonal profile by period, 12-17 vs 18-24 (both sexes) ----------
    periods = [("2008-2010", ctx.PAL[0]), ("2015-2019", ctx.PAL[1]), ("2021-2024", ctx.PAL[2])]
    fig2 = ctx.make_subplots(rows=1, cols=2, shared_yaxes=True, subplot_titles=("Ages 12–17", "Ages 18–24"), horizontal_spacing=0.06)
    for j, g in enumerate(("12-17", "18-24"), 1):
        for pname, col in periods:
            q = PROF[(PROF.period == pname) & (PROF.agegrp == g) & (PROF.sex == "A")].sort_values("month")
            fig2.add_trace(go.Scatter(x=[MONTHS[m - 1] for m in q.month], y=q["index"], mode="lines+markers", name=pname, legendgroup=pname, showlegend=(j == 1), line=dict(color=col, width=2), marker=dict(size=7)), row=1, col=j)
        fig2.add_vrect(x0=4.5, x1=7.5, fillcolor="rgba(128,128,128,.10)", line_width=0, row=1, col=j); fig2.add_hline(y=1, line=dict(color=ctx.MUTED, width=1, dash="dot"), row=1, col=j)
    fig2.update_yaxes(title_text="Monthly rate ÷ period mean", row=1, col=1); ctx.figs["nvss_profile"] = ctx.base(fig2, h=360)

    # ---------- chart 3: decomposition of the 2008-10 -> 2015-19 rise, school months vs summer ----------
    fig3 = go.Figure(); cats = [(g, sx) for g in ("12-17", "18-24", "25-34") for sx in ("F", "M")]; labels = [f"{g} {SEXT[sx].lower()}" for g, sx in cats]
    for lab, key, col in (("School months (Sep–May)", "school", ctx.PAL[3]), ("Summer (Jun–Aug)", "summer", ctx.PAL[6])):
        vals, err_lo, err_hi = [], [], []
        for g, sx in cats:
            d = dec("2008-2010", "2015-2019", g, sx); vals.append(100 * (d[f"ratio_{key}"] - 1)); err_lo.append(100 * (d[f"ratio_{key}"] - d[f"ratio_{key}_lo"])); err_hi.append(100 * (d[f"ratio_{key}_hi"] - d[f"ratio_{key}"]))
        fig3.add_trace(go.Bar(x=labels, y=vals, name=lab, marker_color=col, error_y=dict(type="data", array=err_hi, arrayminus=err_lo, color=ctx.MUTED, thickness=1)))
    fig3.update_layout(barmode="group", bargap=0.3); fig3.update_yaxes(title_text="% change in suicide rate, 2008–10 → 2015–19"); ctx.figs["nvss_decomp"] = ctx.base(fig3, h=360)

    # ---------- tables ----------
    rows = []
    for g in ("12-17", "18-24", "25-34"):
        for sx in ("F", "M", "A"):
            r = rat(RAT, "1999-2019", g, sx); p = reg("season_1999_2019", "summer", g, sx); pdx = reg("season_1999_2019", "dec", g, sx)
            rows.append([g, SEXT[sx], f"{int(r.deaths):,}", r1(r.rate), r1(r.rate_school), r1(r.rate_summer), f"{r.ratio_summer_school:.2f} ({ci(r.lo, r.hi)})", f"{r.ratio_dec_vs_other_school:.2f} ({ci(r.dec_lo, r.dec_hi)})", ctx.fmt(p.coef, p.se, bold_t=1.96)])
    t_season = ctx.table(["Ages", "Sex", "Deaths 1999–2019", "Rate", "Sep–May", "Jun–Aug", "Summer ÷ school ratio (95% CI)", "Dec ÷ other school months", "Poisson log-ratio, summer (SE)"], rows)
    rows = []
    for pre, post in (("2008-2010", "2015-2019"), ("2015-2019", "2021-2024")):
        for g in ("12-17", "18-24", "25-34"):
            for sx in ("F", "M", "A"):
                d = dec(pre, post, g, sx); p = reg("rise_0810_1519" if pre == "2008-2010" else "post_1519_2124", "post_summer", g, sx)
                rows.append([f"{pre} → {post}", g, SEXT[sx], f"{r1(d.rate_pre_school)} → {r1(d.rate_post_school)}", pct(d.pct_change_school), f"{r1(d.rate_pre_summer)} → {r1(d.rate_post_summer)}", pct(d.pct_change_summer), f"{d.ratio_of_ratios_school_vs_summer:.2f} ({ci(d.ror_lo, d.ror_hi)})", ctx.fmt(p.coef, p.se, bold_t=1.96), f"{100 * d.share_increase_school_months:.0f}%"])
    t_dec = ctx.table(["Periods", "Ages", "Sex", "School-month rate", "Change", "Summer rate", "Change", "School ÷ summer ratio of ratios (95% CI)", "Poisson post × summer (SE)", "Share of increase in Sep–May"], rows)
    rows = []
    def cc(c): return (f"{int(c.observed)} / {c.expected_trend:.0f} ({pct(c.pct_vs_trend)}; {pct(c.pct_vs_2019level)})" if pd.notna(c.observed) else "–")
    for g in ("12-17", "18-24", "25-34"):
        for sx in ("F", "M", "A"):
            rows.append([g, SEXT[sx]] + [cc(cov(g, sx, 2020, w)) for w in ("Jan-Feb", "Mar-May", "Jun-Aug", "Sep-Dec")] + [cc(cov(g, sx, 2021, "Jan-May"))])
    t_cov = ctx.table(["Ages", "Sex", "Jan–Feb 2020", "Mar–May 2020 (closures)", "Jun–Aug 2020", "Sep–Dec 2020", "Jan–May 2021"], rows)
    rows = []
    for period in ("1999-2019", "2021-2024"):
        for g in ("12-17", "18-24", "25-34"):
            for sx in ("A", "F", "M"):
                w = {s: WK[(WK.period == period) & (WK.agegrp == g) & (WK.sex == sx) & (WK.season == s)].iloc[0] for s in ("school", "summer", "school_vs_summer_ratio_of_ratios")}
                rows.append([period, g, SEXT[sx], f"{int(w['school'].deaths + w['summer'].deaths):,}", f"{w['school'].weekday_weekend_ratio:.2f} ({ci(w['school'].lo, w['school'].hi)})", f"{w['summer'].weekday_weekend_ratio:.2f} ({ci(w['summer'].lo, w['summer'].hi)})", f"{w['school_vs_summer_ratio_of_ratios'].weekday_weekend_ratio:.2f} ({ci(w['school_vs_summer_ratio_of_ratios'].lo, w['school_vs_summer_ratio_of_ratios'].hi)})"])
    t_wk = ctx.table(["Period", "Ages", "Sex", "Deaths", "Weekday ÷ weekend per-day ratio, Sep–May (95% CI)", "Same, Jun–Aug", "School ÷ summer"], rows)
    lit = ctx.table(["Study", "Data", "Finding on the school calendar"], [
        ['<a href="https://doi.org/10.1016/j.econedurev.2011.04.012">Hansen &amp; Lang 2011</a>, <em>Econ. Educ. Rev.</em>', "State-month suicide rates 1980–2004, NVSS multiple-cause files", "Summer lowers the 14–17 suicide rate by 1.38 per 100,000 (youth overall −0.83); the drop is absent at 19–25, whose summer rate is higher; not explained by weather, economic conditions or seasonal affective disorder"],
        ['<a href="https://doi.org/10.3368/jhr.1222-12710R2">Hansen, Sabia &amp; Schaller 2024</a>, <em>J. Human Resources</em> (NBER WP 30795)', "Restricted county-month NVSS counts 1990–2020, ages 12–18 vs 19–25; SafeGraph school foot traffic", "12–18 suicides 15.6–22.0% below January in June–August and ~19% lower in December; August-start counties rise in August, September-start counties in September; March–May 2020 25–38% below January 2020 (abstract: −25% in March); reopening +12–18%; young adults +1–3% in summer"],
        ['<a href="https://doi.org/10.1016/j.ajem.2015.02.055">Lueck et al. 2015</a>, <em>Am. J. Emerg. Med.</em>', "3,223 pediatric psychiatric ED visits for danger to self/others, one academic ED, 2009–2012", "82.7% of visits in school weeks vs 68.6% of time in school: IRR 2.18 (urinary-tract-infection control 1.25)"],
        ['<a href="https://doi.org/10.1542/peds.2017-2426">Plemmons et al. 2018</a>, <em>Pediatrics</em>', "115,856 suicide-ideation/attempt encounters, 31 children's hospitals, ages 5–17, 2008–2015", "Share of encounters rose from 0.66% to 1.82%; lowest in summer, highest in spring and fall every year, with the seasonal pattern persisting over the rise"],
        ['<a href="https://doi.org/10.1016/j.jpeds.2018.10.017">Carbone, Holzer &amp; Vaughn 2019</a>, <em>J. Pediatrics</em>', "HCUP ED billing data 2010–2014, 874,872 child/adolescent visits", "Largest increase at 12–14 (+82%); higher rates in the school year for children and adolescents, no seasonality for adults"],
        ['<a href="https://doi.org/10.1001/jamanetworkopen.2023.24183">Kim, Krause &amp; Lane 2023</a>, <em>JAMA Netw. Open</em>', "Commercial-claims ED visits and hospitalizations for suicidality, ages 10–19, 2016–2021", "Peak in April (IRR 1.15) and nadir in July (IRR 0.63) in pre-COVID years and 2021; April–May 2020 were the lowest months of that year"],
        ['<a href="https://doi.org/10.15585/mmwr.mm7238a3">Radhakrishnan et al. 2023</a>, <em>MMWR</em>', "NSSP ED visits, ages 5–17, Jan 2018–Jun 2023", "Suicidal-ideation/self-harm visit ratios for fall and spring semesters vs the preceding summer 1.13–2.00 (10–14) and 1.15–1.74 (15–17) in every school year including 2021–22 and 2022–23"],
        ['<a href="https://doi.org/10.1186/s12888-024-06309-7">To et al. 2024</a>, <em>BMC Psychiatry</em>', "CDC WONDER monthly suicides 2015–2020 by age group", "Ages 15–24 are the only group peaking in September–October with a June trough; summer incidence lower than at 25+ in every year"],
    ])

    # ---------- prose ----------
    r17 = {sx: rat(RAT, "1999-2019", "12-17", sx) for sx in ("F", "M", "A")}; r24 = rat(RAT, "1999-2019", "18-24", "A"); r34 = rat(RAT, "1999-2019", "25-34", "A")
    rp = {p: rat(RAT, p, "12-17", "A") for p in ("2008-2010", "2015-2019", "2021-2024")}
    d17 = {sx: dec("2008-2010", "2015-2019", "12-17", sx) for sx in ("F", "M", "A")}; d24 = dec("2008-2010", "2015-2019", "18-24", "A")
    dalt = {k: dec(*k, "12-17", "A") for k in (("1999-2003", "2015-2019"), ("2005-2009", "2015-2019"), ("2008-2010", "2021-2024"))}
    p17 = {sx: reg("rise_0810_1519", "post_summer", "12-17", sx) for sx in ("F", "M", "A")}
    ddd = {sx: reg("ddd_1217_vs_18-24_0810_1519", "teen_post_summer", "12-17 vs 18-24", sx) for sx in ("F", "M", "A")}
    e17 = {sx: dec("2015-2019", "2021-2024", "12-17", sx) for sx in ("F", "M", "A")}
    c17 = {sx: cov("12-17", sx, 2020, "Mar-May") for sx in ("F", "M", "A")}; c24 = cov("18-24", "A", 2020, "Mar-May"); c34 = cov("25-34", "A", 2020, "Mar-May")
    cj17 = cov("12-17", "A", 2020, "Jan-Feb"); cs17 = cov("12-17", "A", 2020, "Jun-Aug"); cf17 = cov("12-17", "A", 2020, "Sep-Dec"); c21 = cov("12-17", "A", 2021, "Jan-May"); c21s = cov("12-17", "A", 2021, "Mar-May")
    def wrow(period, g, s): return WK[(WK.period == period) & (WK.agegrp == g) & (WK.sex == "A") & (WK.season == s)].iloc[0]
    w17 = {s: wrow("1999-2019", "12-17", s) for s in ("school", "summer", "school_vs_summer_ratio_of_ratios")}; w24 = {s: wrow("1999-2019", "18-24", s) for s in ("school", "summer", "school_vs_summer_ratio_of_ratios")}
    a0817 = {sx: (ann("12-17", sx, 2008).rate, ann("12-17", sx, 2019).rate, ann("12-17", sx, 2024).rate) for sx in ("F", "M")}
    def excl(lo, hi): return (lo > 1) or (hi < 1)
    def rel(x): return f"{abs(x):.0f}% {'below' if x < 0 else 'above'}"
    def ror_sentence(d, who):
        if d.ratio_of_ratios_school_vs_summer > 1 and d.ror_lo > 1: return f"for {who} the rise was significantly larger in school months (ratio of ratios {d.ratio_of_ratios_school_vs_summer:.2f}, 95% CI {ci(d.ror_lo, d.ror_hi)})"
        if d.ratio_of_ratios_school_vs_summer < 1 and d.ror_hi < 1: return f"for {who} the rise was significantly larger in summer (ratio of ratios {d.ratio_of_ratios_school_vs_summer:.2f}, 95% CI {ci(d.ror_lo, d.ror_hi)})"
        return f"for {who} the school-month and summer increases are statistically indistinguishable (ratio of ratios {d.ratio_of_ratios_school_vs_summer:.2f}, 95% CI {ci(d.ror_lo, d.ror_hi)})"
    if any(excl(d17[sx].ror_lo, d17[sx].ror_hi) for sx in ("F", "M", "A")): ror_text = "; ".join(ror_sentence(d17[sx], who) for sx, who in (("F", "girls"), ("M", "boys"), ("A", "both sexes together")))
    else: ror_text = "for girls, boys and both sexes together the school-month and summer increases are statistically indistinguishable (ratios of ratios " + "; ".join(f"{d17[sx].ratio_of_ratios_school_vs_summer:.2f}, 95% CI {ci(d17[sx].ror_lo, d17[sx].ror_hi)}" for sx in ("F", "M", "A")) + ")"
    excl_text = f"A rise confined to the school year, with summer flat at its 2008–2010 level, would give a ratio of ratios equal to the school-month ratio itself, {d17['A'].ratio_school:.2f}; the upper confidence limit of {d17['A'].ror_hi:.2f} excludes it and allows at most {100 * (d17['A'].ror_hi - 1):.0f}% more growth in school months than in summer."
    html = f"""<h3 id="nvss">School-calendar seasonality of adolescent suicide and the summer-vs-school decomposition of the rise (NVSS, {y0}–{y1})</h3>
<p>Suicide deaths are the one adolescent-distress series that is counted, not asked, in every month of every year since 1999. The school-pressure (H2) and interaction (H3) hypotheses predict that whatever drove the post-2010 rise operated through the school year, so the increase should be concentrated in September–May; a phone or social-media mechanism that operates year-round (H1) predicts a proportional rise in summer and school months alike. <a href="https://doi.org/10.1016/j.econedurev.2011.04.012">Hansen and Lang (2011)</a> and <a href="https://doi.org/10.3368/jhr.1222-12710R2">Hansen, Sabia and Schaller (2024)</a> established the seasonal pattern itself: suicides at ages 12–18 fall every summer while young-adult suicides do not. Whether the <em>rise</em> of the 2010s followed the same calendar has not, as far as we can find, been tested; we do so here with the public CDC WONDER monthly tabulations of the National Vital Statistics System (ICD-10 X60–X84, Y87.0, *U03), ages 12–17 against 18–24 and 25–34, by sex, with July 1 single-year-age populations as denominators and exposure adjusted for the length of each month ({n_deaths['12-17']:,} suicides at 12–17, {n_deaths['18-24']:,} at 18–24 and {n_deaths['25-34']:,} at 25–34 over {y0}–{y1}). Data for 1999–2020 come from the 1999–2020 database (bridged-race populations) and 2021–2024 from the 2018–2024 single-race database; the two agree exactly on deaths in the overlap years.</p>
{ctx.fig_div('nvss_monthly')}
<p class="caption">Monthly suicide rate per 100,000 person-years at ages 12–17 by sex, 2008–2024; shaded bands are June–August; the orange band marks the March–May 2020 school closures. Monthly counts are ~{int(M[(M.agegrp == '12-17') & (M.sex == 'F') & (M.year.between(2015, 2019))].deaths.mean()):d} for girls and ~{int(M[(M.agegrp == '12-17') & (M.sex == 'M') & (M.year.between(2015, 2019))].deaths.mean()):d} for boys in 2015–19, so single months are noisy.</p>
<h4>The summer drop exists at 12–17 and not at 18–24 or 25–34</h4>
<p>Pooling 1999–2019, the 12–17 suicide rate in June–August is {r17['A'].ratio_summer_school:.2f} times the September–May rate (95% CI {ci(r17['A'].lo, r17['A'].hi)}), a {100 * (1 - r17['A'].ratio_summer_school):.0f}% summer deficit; it is {r17['F'].ratio_summer_school:.2f} for girls and {r17['M'].ratio_summer_school:.2f} for boys. At 18–24 the ratio is {r24.ratio_summer_school:.2f} ({ci(r24.lo, r24.hi)}) and at 25–34 {r34.ratio_summer_school:.2f} ({ci(r34.lo, r34.hi)}): the young-adult and adult summer rates are, if anything, slightly higher than their school-month rates, as in Hansen and Lang. December, when students are out of school for its last ten days, is lower than the other school months at every age (the familiar holiday dip), but by more at 12–17 ({r17['A'].ratio_dec_vs_other_school:.2f}, {ci(r17['A'].dec_lo, r17['A'].dec_hi)}) than at 18–24 ({r24.ratio_dec_vs_other_school:.2f}) or 25–34 ({r34.ratio_dec_vs_other_school:.2f}). A Poisson regression of monthly counts on summer and December indicators with year fixed effects gives the same picture (table), and the magnitudes match Hansen, Sabia and Schaller's 15.6–22.0% summer deficit from restricted county data. The depth of the trough has not changed: the summer ÷ school ratio at 12–17 was {rp['2008-2010'].ratio_summer_school:.2f} in 2008–2010, {rp['2015-2019'].ratio_summer_school:.2f} in 2015–2019 and {rp['2021-2024'].ratio_summer_school:.2f} in 2021–2024.</p>
{t_season}
<p class="caption">Pooled 1999–2019 rates per 100,000 person-years. The summer ÷ school ratio is the June–August rate divided by the September–May rate with a Poisson 95% CI; the Poisson column is the log rate ratio of summer months relative to the other school months (September–May excluding December) from a model with year fixed effects and robust (HC1) standard errors.</p>
<h4>Did the rise follow the school calendar?</h4>
<p>We compare 2008–2010, the trough before the increase, with 2015–2019, the plateau at the top of the pre-pandemic rise (the 2005–2009 and 1999–2003 baselines in <code>nvss_decomposition.csv</code> give the same answer). For girls aged 12–17 the September–May rate rose from {r1(d17['F'].rate_pre_school)} to {r1(d17['F'].rate_post_school)} per 100,000 ({pct(d17['F'].pct_change_school)}), and the June–August rate from {r1(d17['F'].rate_pre_summer)} to {r1(d17['F'].rate_post_summer)} ({pct(d17['F'].pct_change_summer)}); for boys the changes are {pct(d17['M'].pct_change_school)} in school months and {pct(d17['M'].pct_change_summer)} in summer. The test statistic is the ratio of the two period ratios, school-month post ÷ pre over summer post ÷ pre: {ror_text}. {excl_text} Because school months carry {100 * d17['A'].school_person_time_share:.0f}% of the year's person-time, {100 * d17['A'].share_increase_school_months:.0f}% of the absolute increase in annual deaths per 100,000 at 12–17 accrued in September–May, against the {100 * d17['A'].school_person_time_share:.0f}% expected if the rise were seasonally neutral. The Poisson model on monthly counts (month fixed effects, period indicator and a period × summer interaction, exposure offset) gives a post × summer log-ratio of {ctx.fmt(p17['F'].coef, p17['F'].se)} for girls, {ctx.fmt(p17['M'].coef, p17['M'].se)} for boys and {ctx.fmt(p17['A'].coef, p17['A'].se)} pooled; a negative-binomial fit returns the same coefficients. The young-adult comparison behaves as a placebo should: at 18–24 the ratio of ratios is {d24.ratio_of_ratios_school_vs_summer:.2f} ({ci(d24.ror_lo, d24.ror_hi)}), and the triple-difference coefficient (12–17 vs 18–24, post × summer × teen) is {ctx.fmt(ddd['A'].coef, ddd['A'].se)} pooled, {ctx.fmt(ddd['F'].coef, ddd['F'].se)} for girls. Other baselines agree: the ratio of ratios is {dalt[('1999-2003', '2015-2019')].ratio_of_ratios_school_vs_summer:.2f} ({ci(dalt[('1999-2003', '2015-2019')].ror_lo, dalt[('1999-2003', '2015-2019')].ror_hi)}) from 1999–2003, {dalt[('2005-2009', '2015-2019')].ratio_of_ratios_school_vs_summer:.2f} ({ci(dalt[('2005-2009', '2015-2019')].ror_lo, dalt[('2005-2009', '2015-2019')].ror_hi)}) from 2005–2009, and {dalt[('2008-2010', '2021-2024')].ratio_of_ratios_school_vs_summer:.2f} ({ci(dalt[('2008-2010', '2021-2024')].ror_lo, dalt[('2008-2010', '2021-2024')].ror_hi)}) for 2008–2010 against 2021–2024.</p>
{ctx.fig_div('nvss_decomp')}
<p class="caption">Percent change in the suicide rate from 2008–2010 to 2015–2019 in school months (September–May) and summer (June–August), by age group and sex, with Poisson 95% confidence intervals.</p>
{t_dec}
<p class="caption">Rates per 100,000 person-years. The ratio of ratios divides the post ÷ pre rate ratio in school months by the same ratio in summer (above 1 = the rise was concentrated in school months). The Poisson column is the post × summer interaction from a monthly-count model with month fixed effects and an exposure offset (robust SE); the last column is the share of the absolute increase in annual deaths per 100,000 that accrued in September–May (seasonally neutral = 75%).</p>
<p>Extending the comparison past the pandemic, 2021–2024 against 2015–2019: the 12–17 school-month rate changed by {pct(e17['A'].pct_change_school)} and the summer rate by {pct(e17['A'].pct_change_summer)} (ratio of ratios {e17['A'].ratio_of_ratios_school_vs_summer:.2f}, {ci(e17['A'].ror_lo, e17['A'].ror_hi)}); girls {pct(e17['F'].pct_change_school)} vs {pct(e17['F'].pct_change_summer)}, boys {pct(e17['M'].pct_change_school)} vs {pct(e17['M'].pct_change_summer)}. Annual 12–17 rates: girls {r1(a0817['F'][0])} (2008), {r1(a0817['F'][1])} (2019), {r1(a0817['F'][2])} (2024); boys {r1(a0817['M'][0])}, {r1(a0817['M'][1])}, {r1(a0817['M'][2])}.</p>
{ctx.fig_div('nvss_profile')}
<p class="caption">Seasonal profile (monthly rate divided by the period mean, both sexes) in 2008–2010, 2015–2019 and 2021–2024 at ages 12–17 and 18–24; shaded = June–August. The 12–17 trough keeps its depth across the rise.</p>
<h4>2020: closures and reopening</h4>
<p>Expected counts for 2020 and 2021 come from a Poisson model fit to 2015–2019 monthly counts with month fixed effects and a linear year trend, extrapolated with each later month's exposure; a second variant applies the 2015–19 seasonal index to the 2019 rate (the "2019 level"). The two differ for 2021 because the extrapolated trend outruns the plateau that boys' rates had reached by 2018–19, so both are shown. In March–May 2020, 12–17 suicides were {rel(c17['A'].pct_vs_trend)} the trend expectation (ratio {c17['A'].ratio_trend:.2f}, 95% CI {ci(c17['A'].ratio_lo, c17['A'].ratio_hi)}; girls {rel(c17['F'].pct_vs_trend)}, boys {rel(c17['M'].pct_vs_trend)}) and {rel(c17['A'].pct_vs_2019level)} the 2019 level, against {rel(c24.pct_vs_trend)} trend at 18–24 and {rel(c34.pct_vs_trend)} at 25–34. Hansen, Sabia and Schaller report March–May 2020 teen suicides 25–38% below January 2020 (their abstract: −25% in March); the national figures here are of the same order, and January–February 2020 ({rel(cj17.pct_vs_trend)} trend, {rel(cj17.pct_vs_2019level)} the 2019 level) shows that 2020 did not start low. June–August 2020 was {rel(cs17.pct_vs_trend)} trend ({rel(cs17.pct_vs_2019level)} the 2019 level), and September–December 2020, when most districts were in hybrid or remote instruction, was {rel(cf17.pct_vs_trend)} trend but {rel(cf17.pct_vs_2019level)} the 2019 level. January–May 2021, when most districts had returned to in-person instruction, was {rel(c21.pct_vs_trend)} the trend expectation (ratio {c21.ratio_trend:.2f}, {ci(c21.ratio_lo, c21.ratio_hi)}) and {rel(c21.pct_vs_2019level)} the 2019 level; relative to the closure months themselves, March–May 2021 ran {100 * (c21s.rate_observed / c17['A'].rate_observed - 1):.0f}% higher ({c21s.rate_observed:.1f} against {c17['A'].rate_observed:.1f} per 100,000 person-years), the direction of Hansen, Sabia and Schaller's reopening estimate, but whether 2021 was above or below where the pre-pandemic series would have been depends on the counterfactual.</p>
{t_cov}
<p class="caption">Observed / expected suicides from the trend model; in parentheses the percent difference from the trend model and, after the semicolon, from the 2019-level model (2019 annual rate × 2015–19 seasonal index × the window's exposure). Population change is in the exposure.</p>
<h4>Day of week</h4>
<p>WONDER also tabulates deaths by day of week, and its year/month filter lets the weekday table be pooled over school months and summer months separately. Pooling 1999–2019, 12–17 suicides per calendar day are {w17['school'].weekday_weekend_ratio:.2f} times higher on Monday–Friday than on Saturday–Sunday during school months (95% CI {ci(w17['school'].lo, w17['school'].hi)}), with Monday the peak ({w17['school'].per_day_mon:.2f} deaths per Monday against {w17['school'].per_day_sat:.2f} per Saturday), and {w17['summer'].weekday_weekend_ratio:.2f} times higher in summer ({ci(w17['summer'].lo, w17['summer'].hi)}); the school ÷ summer ratio of those ratios is {w17['school_vs_summer_ratio_of_ratios'].weekday_weekend_ratio:.2f} ({ci(w17['school_vs_summer_ratio_of_ratios'].lo, w17['school_vs_summer_ratio_of_ratios'].hi)}). At 18–24 there is no weekday excess in either season ({w24['school'].weekday_weekend_ratio:.2f} in school months, {w24['summer'].weekday_weekend_ratio:.2f} in summer). Part of the adolescent weekday excess therefore survives the summer, but it is larger in term time and absent at the ages that have left school, which makes it a second, within-week trace of school exposure to set beside the summer trough.</p>
{t_wk}
<p class="caption">Deaths per calendar day on Monday–Friday divided by deaths per calendar day on Saturday–Sunday, pooled over the period's school months (September–May) or summer months (June–August), with Poisson 95% CIs; the last column divides the school-month ratio by the summer ratio.</p>
<h4>What the literature already shows</h4>
{lit}
<div class="note"><strong>Assessment.</strong> Two things are established with precision and one is ruled out. First, school exposure raises the <em>level</em> of adolescent suicide: at 12–17 the rate is {100 * (1 - r17['A'].ratio_summer_school):.0f}% lower in June–August than in September–May (95% CI {100 * (1 - r17['A'].hi):.0f}–{100 * (1 - r17['A'].lo):.0f}%), {100 * (w17['school'].weekday_weekend_ratio - 1):.0f}% higher on school days than at weekends, and {rel(c17['A'].pct_vs_trend)} expectation when schools closed in March–May 2020, with none of these patterns at 18–24 or 25–34. That is the premise of H2 and H3, it replicates Hansen, Sabia and Schaller nationally, and it holds in every period from 1999 to 2024. Second, the 2008–10 → 2015–19 rise did not follow the school calendar: school-month and summer rates rose {pct(d17['A'].pct_change_school)} and {pct(d17['A'].pct_change_summer)} (ratio of ratios {d17['A'].ratio_of_ratios_school_vs_summer:.2f}, 95% CI {ci(d17['A'].ror_lo, d17['A'].ror_hi)}), the triple difference against 18–24 is {ctx.fmt(ddd['A'].coef, ddd['A'].se)}, the seasonal profile kept its depth, and the same holds for girls and boys separately and for every alternative baseline. A driver that acted only through the school day, whether academic pressure, school climate or what phones do at school, would have raised September–May faster than June–August; the data exclude a school-only rise and allow at most {100 * (d17['A'].ror_hi - 1):.0f}% faster growth in term time. Third, the pattern that fits is a year-round driver scaling a fixed seasonal profile, which is what H1 (continuous exposure to phones and social media) predicts and a pure H2 account does not; H3 survives only in a form where the interaction operates as much in summer as in term. Caveats: suicide is a rare extreme outcome whose drivers (means, intoxication, contagion) need not match those of the survey-measured distress the rest of the report tracks; summer is not school-free (August starts, summer school, school-based peer networks and anticipatory anxiety carry over); and the 2021 reopening comparison is unresolved between the two counterfactuals ({rel(c21.pct_vs_trend)} trend, {rel(c21.pct_vs_2019level)} the 2019 level). The school effect on the level is real and large; the rise ran through summer as much as through the school year.</div>"""
    return {"nvss": html}
